-- 090512d9 English: Integrations
-- Context: Top-level tab of the settings window (next to General, Conditions, Functions ...):
--     integrations with other addons.
[1505] = "Интеграции",
-- 90c92d4c English: Lua editor
-- Context: Title of the Lua editor help window, and the name of a Lua editor settings row in the
--     profile comparison.
[1506] = "Редактор Lua",
-- d8cfde4d English: Choose optional addon integrations.
[1507] = "Выберите необязательные интеграции с аддонами.",
-- 67af476d English: Automatic uses an available editor integration, with built-in syntax
--     highlighting as its fallback. Plain text disables highlighting. Apply changes the editor used
--     the next time you open a custom condition.
[1508] = "«Автоматически» использует доступную интеграцию редактора, а при её отсутствии — встроенную подсветку синтаксиса. «Простой текст» отключает подсветку. «Применить» меняет редактор, используемый при следующем открытии пользовательского условия.",
-- 9fe3f474 English: Loaded; editor integration not connected.
[1509] = "Загружен; интеграция редактора не подключена.",
-- a79eae91 English: Not loaded.
[1510] = "Не загружен.",
-- 87b30347 English: These addons are optional. Only connected editor providers appear in the Editor
--     menu. Choosing an unavailable or failing editor falls back to the built-in editor.
[1511] = "Эти аддоны необязательны. В меню «Редактор» появляются только подключённые поставщики редактора. При выборе недоступного или сбойного редактора используется встроенный.",
-- f1fa67bf English: Choose the editor for custom Lua conditions. Built In syntax highlighting and
--     Plain text work without another addon. Automatic uses a registered optional provider when
--     available and falls back safely. Apply saves the choice; an open editor keeps its current
--     provider until reopened. LuaWorkbench and WowLua loading status is shown separately from
--     integration availability.
[1512] = "Выберите редактор для пользовательских условий Lua. Встроенная подсветка синтаксиса и простой текст работают без других аддонов. «Автоматически» использует зарегистрированного необязательного поставщика, если он доступен, и безопасно возвращается к встроенному. «Применить» сохраняет выбор; открытый редактор сохраняет текущего поставщика до повторного открытия. Состояние загрузки LuaWorkbench и WowLua показывается отдельно от доступности интеграции.",
-- dfab6835 English: Invalid condition: %s
-- %s #1: %s #1: why the custom condition is invalid, a short reason, e.g. "unexpected symbol near end"
[1513] = "Некорректное условие: %s",
-- a3d021a9 English: Unavailable condition: %s
-- %s #1: %s #1: the description of the condition, e.g. "In Combat"
[1514] = "Недоступное условие: %s",
-- ffb313cc English: This condition definition is disabled. Rotations using it are unavailable.
[1515] = "Определение этого условия отключено. Использующие его ротации недоступны.",
-- 12f67f85 English: Availability
[1516] = "Доступность",
-- ef8f927d English: Edit fields
-- Context: Row text and tooltip in the custom condition source preview when a condition has no
--     named field yet: invites editing the condition's input fields (verb phrase).
[1517] = "Изменить поля",
-- 9f088dbe English: Advanced
-- Context: Checkbox at the top right of the schema editor of a custom condition: switches to the
--     raw schema editor (equivalent text form) instead of the graphical field editor.
[1518] = "Дополнительно",
-- bd82cf16 English: Number
-- Context: Value type in the condition field type dropdown: a numeric value.
[1519] = "Число",
-- a066ff92 English: Boolean
-- Context: Value type in the condition field type dropdown: true/false.
[1520] = "Логическое",
-- 5f3107cf English: Condition list
-- Context: Value type in the condition field type dropdown: a list of conditions.
[1521] = "Список условий",
-- c5025e68 English: Record / map
-- Context: Value type in the condition field type dropdown: a record, i.e. a table of named values
--     (key/value map).
[1522] = "Запись / таблица",
