[1523] = "Допустимые типы / варианты списка",
-- a9b310ef English: Invalid field schema: %s
-- %s #1: %s #1: what is wrong with the field schema, a short code or the field key, e.g. "invalid-required-fields" (shown as-is)
[1524] = "Некорректная схема полей: %s",
-- 76900f1b English: Back
-- Context: Label of the back-navigation control in the embedded Lua editor's API knowledge window
--     (go to the previous page).
[1525] = "Назад",
-- 02dbfe6e English: Named fields. Choose a type, then edit its children for nested data.
[1526] = "Именованные поля. Выберите тип, затем измените вложенные элементы для вложенных данных.",
-- 8eba81e3 English: Allowed types. A nested record or type list describes each item in a list.
[1527] = "Допустимые типы. Вложенная запись или список типов описывает каждый элемент списка.",
-- 130a1408 English: Showing the first 200 fields. Use Advanced schema for larger definitions.
[1528] = "Показаны первые 200 полей. Для больших определений используйте расширенную схему.",
-- 5f42d901 English: Add field
-- Context: Button in the field schema editor: adds a new input field to the custom condition (verb
--     phrase).
[1529] = "Добавить поле",
-- cb4190b5 English: Tag color
-- Context: Tooltip of the colored swatch in a tag entry in a selector list: the tag's color.
[1530] = "Цвет метки",
-- 08b91fc6 English: Type a tag and press Enter, or choose an existing tag. Click a tag to remove
--     it; use the search results to change tag colors.
[1531] = "Введите метку и нажмите Enter или выберите существующую. Нажмите на метку, чтобы удалить её; цвета меток меняются в результатах поиска.",
-- cbf6490e English: Search existing tags and select any number of them. Click a selected tag to
--     remove it; use the search results to change tag colors.
[1532] = "Ищите существующие метки и выбирайте любое их количество. Нажмите на выбранную метку, чтобы убрать её; цвета меток меняются в результатах поиска.",
-- 45fa2eb3 English: Click to remove this tag. Use the search results to change tag colors.
[1533] = "Нажмите, чтобы удалить эту метку. Цвета меток меняются в результатах поиска.",
-- 84cfb5be English: Each callback keeps its own pending text while switching tabs. Undo and Redo
--     edit that callback buffer. Reset restores its last saved code, or the template for a new
--     condition, and can be undone. The main Apply saves and registers all callback buffers and
--     metadata; Discard drops the whole draft. Leaving with changes offers Apply, Discard or
--     Cancel. Check syntax runs no callbacks.
[1534] = "Каждый обратный вызов хранит свой несохранённый текст при переключении вкладок. «Отменить» и «Повторить» правят буфер этого обратного вызова. «Сбросить» восстанавливает последний сохранённый код или шаблон для нового условия, и это можно отменить. Основное «Применить» сохраняет и регистрирует все буферы обратных вызовов и метаданные; «Отменить изменения» отбрасывает весь черновик. При уходе с изменениями предлагается «Применить», «Отменить изменения» или «Отмена». «Проверить синтаксис» не запускает обратные вызовы.",
-- 047aff36 English: No native Lua editor has been opened this session.
[1535] = "В этом сеансе встроенный редактор Lua не открывался.",
-- 5472dd28 English: Lua input diagnostics
-- Context: Title of the report window that shows Lua editor input diagnostics, for testers to copy.
[1536] = "Диагностика ввода Lua",
-- 5c126363 English: Native input test
-- Context: Title of a test dialog (Lua editor input probe): checks the game's native text input.
[1537] = "Тест встроенного ввода",
