-- Context: Phrase for the unit choice 'group leader' in condition summaries, e.g. '<this> {{!is|is
--     not}} your group's leader'; the next string is its possessive form.
[1982] = "лидер вашей группы",
-- 1d3180fa English: your group's leader's
-- Context: Possessive form of 'your group's leader' used in condition summaries before a noun, e.g.
--     'your group's leader's health'.
[1983] = "лидера вашей группы",
-- fad43537 English: Absolute health target (negative means deficit) or percentage fraction.
[1984] = "Абсолютный порог здоровья (отрицательный — дефицит) или доля в процентах.",
-- 29a55788 English: All original results, preserving nil positions and return count.
[1985] = "Все исходные результаты с сохранением позиций nil и числа возвращаемых значений.",
-- c7e69e75 English: Apply the legacy integer or canonical numeric-string spelling test. Numbers use
--     floor equality; strings must equal the spelling obtained after numeric conversion and floor.
--     Other types return false. This is not a finite-number validator.
[1986] = "Применить старую проверку записи целого числа или канонической числовой строки. Числа сравниваются после округления вниз; строки должны совпадать с записью, полученной после числового преобразования и округления вниз. Для других типов возвращается false. Это не проверка конечности числа.",
-- 69eb2e21 English: Arguments forwarded unchanged to the observed function.
[1987] = "Аргументы, передаваемые без изменений наблюдаемой функции.",
-- 1d513028 English: Arguments forwarded unchanged; types, identity, arity and nil positions
--     distinguish cache entries.
[1988] = "Аргументы передаются без изменений; типы, идентичность, количество и позиции nil различают записи кэша.",
-- 3e8d2702 English: Availability or query-validation reason for a nil level observation.
[1989] = "Причина недоступности или ошибки проверки запроса для наблюдения уровня, равного nil.",
-- e2ffe9af English: Availability or query-validation reason for a nil level.
[1990] = "Причина недоступности или ошибки проверки запроса для уровня, равного nil.",
-- 66134514 English: Availability or query-validation reason when no current state can be read.
[1991] = "Причина недоступности или ошибки проверки запроса, если текущее состояние нельзя прочитать.",
-- 77b92c6d English: Availability or query-validation reason when the whole observation is
--     unavailable.
[1992] = "Причина недоступности или ошибки проверки запроса, если всё наблюдение недоступно.",
-- 11483c22 English: Availability or validation reason for a nil result.
[1993] = "Причина недоступности или ошибки проверки для результата nil.",
-- bd62d347 English: Availability or validation reason when the record is nil.
[1994] = "Причина недоступности или ошибки проверки, если запись равна nil.",
-- cab01ca9 English: Availability or validation reason when the result is nil.
[1995] = "Причина недоступности или ошибки проверки, если результат равен nil.",
-- 37cddc45 English: Availability reason for a nil result.
[1996] = "Причина недоступности для результата nil.",
-- eced4849 English: Availability reason when resolution fails; nil on success.
[1997] = "Причина недоступности при неудачном разрешении; nil при успехе.",
-- 09403547 English: Cache an observation after it returns a non-nil value; retry observations whose
--     entire return tuple is nil. Uses the same exact argument keys as getCached.
[1998] = "Кэшировать наблюдение после того, как оно вернуло значение не nil; повторять наблюдения, весь кортеж результатов которых равен nil. Использует те же точные ключи аргументов, что и getCached.",
-- ec80f70e English: Calculate a checked health-history rate using an explicit finite window and
--     clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array
--     holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows
--     and accumulation bins across both streams; excess or invalid consumed arithmetic returns
--     unavailable, never a partial estimate or clamp. This new API has its own source identity;
--     historical trend functions remain unchanged.
[1999] = "Вычислить проверенную скорость изменения здоровья по истории с явными конечными окном и часами. Сохраняются упорядоченное взвешивание, построчное каноническое округление на лету, пропущенные потоки, дыры в массивах, дробные ключи и итоговый возраст просмотренных записей. Фиксированный бюджет в 4096 единиц покрывает просмотренные строки и ячейки накопления в обоих потоках; превышение или некорректная арифметика возвращает «недоступно», а не частичную оценку или усечение. У этого нового API своя идентичность исходного кода; исторические функции тренда не меняются.",
-- e3a904cc English: Call an observation once per cache and exact argument tuple, including nil
--     results. Pass the evaluation cache to share observations within a recommendation cycle; nil
--     cache calls directly.
[2000] = "Вызвать наблюдение один раз на кэш и точный кортеж аргументов, включая результаты nil. Передайте кэш вычисления, чтобы делиться наблюдениями в пределах цикла рекомендаций; при nil вызов выполняется напрямую.",
-- cb8a709c English: Callback invoked after changing the selected unit.
[2001] = "Обратный вызов после смены выбранного юнита.",
-- f4755bc2 English: Callback receiving the committed spell value.
[2002] = "Обратный вызов, получающий подтверждённое значение заклинания.",
-- 8473e032 English: Caller-owned evaluation observation cache; nil queries afresh.
[2003] = "Кэш наблюдений вычисления, принадлежащий вызывающему; при nil запрос выполняется заново.",
-- d07ec966 English: Capability or clock observation availability reason.
[2004] = "Причина недоступности возможности или наблюдения часов.",
-- aca2f51b English: Capability or observation availability reason for a nil class.
[2005] = "Причина недоступности возможности или наблюдения для класса nil.",
-- fb8dd5ac English: Check whether a spell can be recommended now, allowing a spell whose remaining
--     cooldown ends with the current global cooldown. On Retail and Forever, where cooldown times
--     are secret in combat, readiness comes from the never-secret isEnabled, isActive and isOnGCD
--     flags instead. This checks cooldown readiness only; it does not check learned status, range
--     or resource usability. Pass evaluation time from evalStart or GetTime().
[2006] = "Проверяет, можно ли рекомендовать заклинание сейчас, допуская заклинание, оставшееся восстановление которого заканчивается вместе с текущим общим временем восстановления. В Retail и Forever, где время восстановления в бою скрыто, готовность вместо этого определяется по никогда не скрываемым флагам isEnabled, isActive и isOnGCD. Проверяется только готовность по восстановлению; изученность, дальность и достаточность ресурсов не проверяются. Передайте время вычисления из evalStart или GetTime().",
-- 1081f5fc English: Check whether a table has a non-nil value at a key. A stored false value still
--     counts as present; this does not scan table values.
[2007] = "Проверить, есть ли в таблице значение не nil по ключу. Сохранённое значение false также считается присутствующим; значения таблицы не просматриваются.",
-- 3f1a5911 English: Checkbox widget with boolean value and callback methods.
[2008] = "Виджет флажка с логическим значением и методами обратного вызова.",
-- 8373609b English: Choose the supplied player value only for the literal player unit token; every
--     other unit selects the nonplayer value. Selected false and nil values are preserved.
[2009] = "Выбрать переданное значение для игрока только для буквального токена юнита player; любой другой юнит выбирает значение не для игрока. Выбранные значения false и nil сохраняются.",
-- 68e9defe English: Classification, validation or availability reason for a nil result.
[2010] = "Причина классификации, проверки или недоступности для результата nil.",
-- 7fc7159a English: Classify a numeric item as a glyph for the requested class, using guarded
--     native item metadata. Class is optional and defaults to the readable player class. This
--     establishes item classification only, not equipped status or an item-to-glyph-spell ID
--     mapping.
[2011] = "Определить, является ли числовой предмет символом для запрошенного класса, используя защищённые встроенные метаданные предмета. Класс необязателен и по умолчанию равен читаемому классу игрока. Устанавливается только классификация предмета, а не то, надет ли он, и не соответствие предмета ID заклинания символа.",
-- 355b4c25 English: Client-family, query-validation or required-observation availability reason for
--     a nil result.
[2012] = "Причина недоступности по семейству клиента, проверке запроса или обязательному наблюдению для результата nil.",
-- 56d0a810 English: Client-policy, capability, call or observation availability reason for a nil
--     form.
[2013] = "Причина недоступности по политике клиента, возможности, вызову или наблюдению для облика nil.",
-- fffddfca English: Client-policy, capability, call or observation availability reason for a nil
--     record.
[2014] = "Причина недоступности по политике клиента, возможности, вызову или наблюдению для записи nil.",
-- 7a0f627b English: Client-policy, native-call or required membership availability reason for a nil
--     record.
[2015] = "Причина недоступности по политике клиента, встроенному вызову или обязательному членству для записи nil.",
-- 0a8d99a6 English: Closed kind: runner, resist or immune.
[2016] = "Закрытый вид: runner, resist или immune.",
-- 6999f76c English: Closed scalar kind: current or maximum.
[2017] = "Закрытый вид скаляра: current или maximum.",
-- a7224c57 English: Collect table keys and sort them by their associated values using Lua less-than
--     comparison. This sorts values rather than key names; equal values have no guaranteed key
--     order.
[2018] = "Собрать ключи таблицы и отсортировать их по связанным значениям через сравнение Lua «меньше». Сортируются значения, а не имена ключей; при равных значениях порядок ключей не гарантирован.",
-- 508c105b English: Combat-policy, capability, observation or scan-budget reason for a nil count.
[2019] = "Причина по боевой политике, возможности, наблюдению или бюджету сканирования для числа nil.",
-- 14b9d8a2 English: Combined signed weighted rate from the original formula; malformed or nonfinite
--     inputs retain the legacy error/numeric behavior.
[2020] = "Общая знаковая взвешенная скорость по исходной формуле; при некорректных или бесконечных входных данных сохраняется прежнее поведение ошибки/числа.",
-- ee842735 English: Compare the selected unit creature ID with one existing saved creature-type
--     key. Resolve the fixed key-to-ID identity in one private executable mapper; gameplay matching
--     does not depend on the mutable localized UI caption map. Share complete native observations
--     within the supplied evaluation-pass cache by actual observer, receiver and unit, including
--     absence and unavailable reasons. Known absence or a known different ID returns false; an
--     unavailable required observation returns nil with a reason. No longterm state or caption
--     mutation is added.
[2021] = "Сравнить ID существа выбранного юнита с одним существующим сохранённым ключом типа существа. Фиксированное соответствие ключа и ID определяется одним закрытым исполняемым сопоставителем; совпадение в игре не зависит от изменяемой таблицы локализованных подписей. Полные встроенные наблюдения разделяются в переданном кэше прохода вычисления по фактическому наблюдателю, получателю и юниту, включая отсутствие и причины недоступности. Известное отсутствие или известный другой ID возвращают false; недоступное обязательное наблюдение возвращает nil с причиной. Долговременное состояние и изменение подписей не добавляются.",
-- 098e89f6 English: Compare two exact unit tokens using UnitIsUnit after checking only the first
--     token with UnitExists. A readable absent first unit returns false without comparing. Required
--     missing, failed, restricted or malformed observations return nil with a reason. No second
--     existence query, GUID lookup or inferred identity is added.
[2022] = "Сравнить два точных токена юнитов через UnitIsUnit после проверки только первого токена через UnitExists. Читаемое отсутствие первого юнита возвращает false без сравнения. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Второй запрос существования, поиск GUID или выведенная идентичность не добавляются.",
-- f92fafbd English: Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS,
--     GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and
--     return nil; operands must support the selected Lua operation.
[2023] = "Сравнить два значения с помощью идентификатора оператора RM: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS или DIVISIBLE. Некорректные операторы выдают предупреждение и возвращают nil; операнды должны поддерживать выбранную операцию Lua.",
-- 4d1da429 English: Comparison operator key, such as EQUALS or LESSTHAN.
[2024] = "Ключ оператора сравнения, например EQUALS или LESSTHAN.",
-- 8d6dc0da English: Comparison result, or nil for an unknown operator.
[2025] = "Результат сравнения или nil для неизвестного оператора.",
-- 45e7a5a6 English: Comparison text retaining named Boolean alternative markup.
[2026] = "Текст сравнения с сохранённой разметкой именованных логических вариантов.",
-- beb1fd9a English: Complete matching class count, including zero, or nil when unavailable.
[2027] = "Полное число совпадающих классов, включая ноль, или nil, если недоступно.",
-- 3abb0dce English: Complete nonnegative observed count including zero, or nil when unavailable.
[2028] = "Полное неотрицательное наблюдаемое число, включая ноль, или nil, если недоступно.",
-- a3cbc46a English: Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and
--     DoLayout.
[2029] = "Контейнер условия, поддерживающий SetLayout, AddChild, SetUserData, SetWidth и DoLayout.",
-- 1edda05a English: Condition value record containing spell, ranked and disabled fields; updated in
--     place.
[2030] = "Запись значения условия с полями spell, ranked и disabled; обновляется на месте.",
-- bd948209 English: Condition value record updated when a unit is chosen.
[2031] = "Запись значения условия, обновляемая при выборе юнита.",
-- 49082497 English: Configured unit selector; add it with parent:AddChild(widget).
[2032] = "Настроенный выбор юнита; добавьте его через parent:AddChild(widget).",
-- 93e87554 English: Copy a table using tostring of each original key as the destination key. Values
--     retain their original identities. Colliding stringified keys overwrite each other in
--     unspecified pairs traversal order.
[2033] = "Скопировать таблицу, используя tostring каждого исходного ключа как ключ назначения. Значения сохраняют исходную идентичность. Совпадающие строковые ключи перезаписывают друг друга в неопределённом порядке обхода pairs.",
-- dcd01801 English: Count all entries visited by pairs, including false values and sparse numeric
--     or nonnumeric keys. A nil table has length zero.
[2034] = "Посчитать все записи, обходимые pairs, включая значения false и разреженные числовые или нечисловые ключи. У таблицы nil длина ноль.",
-- 7ee6eac7 English: Count matching class tokens in the current fixed roster. Read group membership
--     first; when requested, raid membership selects raid1 through raid40 without a separate player
--     fact. Solo and party paths read player first, then party1 through party4 when grouped. A
--     complete known roster returns a count, including zero; any required unavailable fact returns
--     nil with a reason. Complete observations share the evaluation-pass cache; no player class
--     persists across passes. Archived raw callbacks retain their original load-time class
--     separately.
[2035] = "Посчитать совпадающие токены классов в текущем фиксированном составе. Сначала читается членство в группе; при запросе членство в рейде выбирает raid1–raid40 без отдельного факта об игроке. В одиночку и в группе сначала читается player, затем party1–party4, если вы в группе. Полный известный состав возвращает число, включая ноль; любой недоступный обязательный факт возвращает nil с причиной. Полные наблюдения разделяют кэш прохода вычисления; класс игрока между проходами не сохраняется. Архивные исходные обратные вызовы отдельно хранят свой класс на момент загрузки.",
-- ddfd3a7c English: Count only GUID-keyed units already in the observed membership snapshot. Verify
--     current token identity before using the published threat observer; known absent or reused
--     tokens are excluded without adding replacements. Complete identity and threat observations
--     share only the supplied evaluation cache, while membership is traversed fresh. Known nonenemy
--     or optional nil threat is not counted; required unreadable, malformed or failed facts make
--     the entire result unavailable. This does not enumerate a complete roster, apply a range
--     filter or modify tracked records.
[2036] = "Учитывать только юниты с ключом GUID, уже входящие в наблюдаемый снимок состава. Перед использованием опубликованного наблюдателя угрозы проверяется текущая идентичность токена; известные отсутствующие или переиспользованные токены исключаются без замены. Полные наблюдения идентичности и угрозы разделяют только переданный кэш вычисления, а состав обходится заново. Известные не-противники или необязательная угроза nil не учитываются; нечитаемые, повреждённые или неудачные обязательные факты делают весь результат недоступным. Полный состав не перечисляется, фильтр дальности не применяется, отслеживаемые записи не меняются.",
-- 02e149c6 English: Create a condition field container with RM-owned List, Table and responsive
--     spell-field layouts. It accepts registered native condition widgets; add children with
--     AddChild and attach the group to the callback parent.
[2037] = "Создать контейнер полей условия с принадлежащими RM раскладками List, Table и адаптивной раскладкой полей заклинаний. Он принимает зарегистрированные встроенные виджеты условий; добавляйте дочерние элементы через AddChild и прикрепите группу к родителю обратного вызова.",
-- 24b26357 English: Create a configured unit selector bound to a condition value record. Returns
--     the widget for the caller to add to the condition callback parent.
[2038] = "Создать настроенный выбор юнита, привязанный к записи значения условия. Возвращает виджет, который вызывающий добавляет к родителю обратного вызова условия.",
-- 704feebd English: Create a native boolean condition control. Configure SetLabel, SetValue,
--     SetDisabled and OnValueChanged; add it with parent:AddChild(widget).
[2039] = "Создать встроенный логический элемент условия. Настройте SetLabel, SetValue, SetDisabled и OnValueChanged; добавьте его через parent:AddChild(widget).",
-- d67fc3b8 English: Create a native button using the shared condition widget lifecycle and
--     workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction;
--     OnClick receives the mouse button. Add it to the callback parent with
--     parent:AddChild(widget).
[2040] = "Создать встроенную кнопку с общим жизненным циклом виджетов условий и темой рабочего окна. SetText, SetDisabled и SetCallback настраивают подпись и взаимодействие; OnClick получает кнопку мыши. Добавьте её к родителю обратного вызова через parent:AddChild(widget).",
-- d4341110 English: Create a native condition selector. SetList accepts key-to-label or
--     key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with
--     parent:AddChild(widget).
[2041] = "Создать встроенный список выбора условия. SetList принимает таблицы ключ–подпись или ключ–запись; SetValue выбирает ключ, а OnValueChanged сообщает об изменениях. Добавьте его через parent:AddChild(widget).",
-- e149229e English: Create a native image control using the condition widget lifecycle. SetImage
--     and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and
--     OnLeave use the shared callback contract. Add the control to the callback parent with
--     parent:AddChild(widget).
[2042] = "Создать встроенный элемент изображения с жизненным циклом виджетов условий. SetImage и SetImageSize выбирают текстуру; SetText при желании добавляет подпись. OnClick, OnEnter и OnLeave используют общий контракт обратных вызовов. Добавьте элемент к родителю обратного вызова через parent:AddChild(widget).",
-- b943d164 English: Create a native numeric condition input with a slider and typed numeric field.
--     Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports
--     committed values. Add it with parent:AddChild(widget).
[2043] = "Создать встроенный числовой ввод условия с ползунком и полем для числа. Настройте SetSliderValues, SetValue, SetIsPercent и SetCallback; OnValueChanged сообщает подтверждённые значения. Добавьте его через parent:AddChild(widget).",
-- a67c621c English: Create a native position pad using the shared directional controls.
--     OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and
--     the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the
--     callback parent with parent:AddChild(widget).
[2044] = "Создать встроенную панель положения с общими кнопками направлений. OnOffsetChanged сообщает направление по горизонтали и вертикали, было ли нажато «Центрировать», и шаг (один или десять с Shift). SetDisabled управляет взаимодействием; добавьте панель к родителю обратного вызова через parent:AddChild(widget).",
-- 25defe9e English: Create a native text input using the condition widget contract. SetLabel,
--     SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the
--     callback parent with parent:AddChild(widget).
[2045] = "Создать встроенный текстовый ввод по контракту виджетов условий. SetLabel, SetText, SetDisabled и SetCallback настраивают его; OnEnterPressed подтверждает текст. Добавьте его к родителю обратного вызова через parent:AddChild(widget).",
-- edff3bd0 English: Create a shallow filtered copy despite the historical deepcopy name. Nested
--     values retain their original identities and the source metatable is not copied. By default
--     exclude keys listed among except values; invert true includes only listed keys. Nil input
--     returns nil.
[2046] = "Создать неглубокую отфильтрованную копию, несмотря на историческое название deepcopy. Вложенные значения сохраняют исходную идентичность, метатаблица источника не копируется. По умолчанию исключаются ключи, перечисленные в значениях except; invert true включает только перечисленные ключи. При входе nil возвращается nil.",
-- ccc11c66 English: Create a spell input with suggestions, validation and spell-link support for
--     custom condition widgets. The update callback owns saving a chosen value; add the returned
--     widget to the callback parent.
[2047] = "Создать поле ввода заклинания с подсказками, проверкой и поддержкой ссылок на заклинания для виджетов пользовательских условий. Сохранение выбранного значения выполняет обратный вызов обновления; добавьте возвращённый виджет к родителю обратного вызова.",
-- 4736bce4 English: Create a transient named condition summary. Use {name} for scalar values and
--     {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape
--     literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their
--     percent signs, links, colors or braces. Typed predicate values participate in primary
--     selection. Templates, values and rendered text are bounded; malformed input renders a
--     localized unavailable summary. This changes presentation only and runs no condition
--     observations.
[2048] = "Создать временную именованную сводку условия. Используйте {name} для скалярных значений и {{positive|negative}} для вариантов предиката; основной вариант помечайте префиксом !. Буквальные двойные фигурные скобки экранируйте как {{{{ и }}}}. Значения вставляются буквально, без разбора знаков процента, ссылок, цветов и скобок. Типизированные значения предикатов участвуют в выборе основного варианта. Шаблоны, значения и итоговый текст ограничены по размеру; при некорректном вводе показывается локализованная сводка «недоступно». Меняется только отображение, наблюдения условий не выполняются.",
-- 7735b638 English: Create a typed comparison predicate for a named condition phrase. Positive
--     wording uses the original captured operator map and negative wording uses the current negated
--     operator map. A primary predicate takes precedence over qualifiers; only the first eligible
--     predicate negates. Unknown operators use the existing operator placeholder. This formats
--     wording without comparing values or evaluating a condition.
[2049] = "Создать типизированный предикат сравнения для именованной фразы условия. Положительная формулировка использует исходную захваченную таблицу операторов, а отрицательная — текущую таблицу отрицаемых операторов. Основной предикат имеет приоритет над уточнениями; отрицается только первый подходящий предикат. Неизвестные операторы используют существующий заполнитель оператора. Форматируется только формулировка, без сравнения значений и вычисления условия.",
-- ddea308b English: Create an iterator over a sorted snapshot of table keys. Default ordering
--     compares keys; a custom order callback receives the original table and two keys. Values are
--     read from the original table when each key is yielded. The legacy iterator ends when the next
--     captured key is nil or false.
[2050] = "Создать итератор по отсортированному снимку ключей таблицы. По умолчанию сравниваются ключи; пользовательский обратный вызов порядка получает исходную таблицу и два ключа. Значения читаются из исходной таблицы в момент выдачи каждого ключа. Старый итератор заканчивается, когда следующий захваченный ключ равен nil или false.",
-- 629b2567 English: Create native wrapping text that measures its height from its width and font.
--     SetText, SetFont or SetFontObject configure its contents. Add it to the callback parent with
--     parent:AddChild(widget) so layout can track its measured height.
[2051] = "Создать встроенный переносимый текст, высота которого измеряется по ширине и шрифту. Содержимое настраивается через SetText, SetFont или SetFontObject. Добавьте его к родителю обратного вызова через parent:AddChild(widget), чтобы раскладка учитывала измеренную высоту.",
-- c58c9a9a English: Create native wrapping text with optional leading image and pointer callbacks.
--     SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition
--     callback contract. Add it to the callback parent with parent:AddChild(widget); callbacks
--     expire when its lease is released.
[2052] = "Создать встроенный переносимый текст с необязательным изображением в начале и обратными вызовами указателя. SetImage и SetImageSize настраивают изображение; OnEnter, OnLeave и OnClick используют контракт обратных вызовов условий. Добавьте его к родителю обратного вызова через parent:AddChild(widget); обратные вызовы перестают действовать после освобождения элемента.",
-- fa988d31 English: Current evaluation time in seconds from GetTime(), normally evalStart.
[2053] = "Текущее время вычисления в секундах по GetTime(), обычно evalStart.",
-- c7fd7453 English: Current positive visibility distance in yards; nil when unavailable.
[2054] = "Текущая положительная дистанция видимости в метрах; nil, если недоступна.",
-- 574eed72 English: Current unit token whose distance from the player should be observed.
[2055] = "Текущий токен юнита, расстояние до которого от игрока нужно наблюдать.",
-- 83a1023e English: Damage/heals arrays of time/value rows; only selected streams are consumed.
[2056] = "Массивы урона/исцеления из строк время/значение; используются только выбранные потоки.",
-- 38e0b44b English: Decimal places, default zero; negative values round to tens or larger powers of
--     ten.
[2057] = "Число знаков после запятой, по умолчанию ноль; отрицательные значения округляют до десятков или больших степеней десяти.",
-- c1094708 English: Dense array of keys sorted by associated value.
[2058] = "Плотный массив ключей, отсортированных по связанному значению.",
-- 7de55bf4 English: Dense array of nonempty text fields.
[2059] = "Плотный массив непустых текстовых полей.",
-- ba17b32f English: Destination array modified in place.
[2060] = "Массив назначения, изменяемый на месте.",
-- 9d65688a English: Display lookup table.
[2061] = "Таблица отображения.",
-- 763bf095 English: Estimate signed health change from weighted damage and healing history. Damage
--     contributes a negative rate and healing a positive rate. Read the live profile window when no
--     window is supplied, use the live clock and legacy rounding service, and preserve the existing
--     weighting and rounded-age calculation. This helper does not validate or sanitize history,
--     clamp timestamps, or guarantee finite results.
[2062] = "Оценить знаковое изменение здоровья по взвешенной истории урона и исцеления. Урон даёт отрицательную скорость, исцеление — положительную. Если окно не передано, читается действующее окно профиля; используются действующие часы и старая служба округления, сохраняются прежнее взвешивание и расчёт округлённого возраста. Этот помощник не проверяет и не очищает историю, не ограничивает метки времени и не гарантирует конечный результат.",
-- c95e98a7 English: Estimate time until selected health. Cache complete native identity and lazy
--     scalar observations per evaluation pass, while provider, history, window, clock and forecast
--     stay live. Exact target equality returns zero before history work. Preserve deliberate
--     no-estimate false and initialized-zero results for zero or opposite rates; required invalid
--     facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent
--     a partial estimate.
[2063] = "Оценить время до выбранного уровня здоровья. Полные встроенные наблюдения идентичности и ленивые скалярные наблюдения кэшируются на проход вычисления, а поставщик, история, окно, часы и прогноз остаются действующими. Точное совпадение с целевым значением возвращает ноль до работы с историей. Сохраняются намеренные результаты false (нет оценки) и инициализированного нуля для нулевой или противоположной скорости; некорректные обязательные факты, переполнение или исчерпание бюджета в 4096 единиц дают «недоступно». История никогда не меняется, частичная оценка не придумывается.",
-- 52a17c6c English: Evaluation cache, or nil to bypass caching.
[2064] = "Кэш вычисления или nil, чтобы обойти кэширование.",
-- 79697e3a English: Evaluation-pass cache for complete unit observations; nil observes directly.
--     Different selected keys reuse the same unit snapshot.
[2065] = "Кэш прохода вычисления для полных наблюдений юнита; при nil наблюдение выполняется напрямую. Разные выбранные ключи переиспользуют один снимок юнита.",
-- bd88f3f9 English: Evaluation-pass cache, or nil for fresh observations.
[2066] = "Кэш прохода вычисления или nil для новых наблюдений.",
-- d022fab6 English: Evaluation-pass cache, or nil to observe identity directly. Resource mapping is
--     resolved live on each invocation.
[2067] = "Кэш прохода вычисления или nil для прямого наблюдения идентичности. Сопоставление ресурсов определяется заново при каждом вызове.",
-- 0900784b English: Evaluation-pass cache, or nil to observe identity directly. Successful player
--     class observations may use the existing longterm identity cache; resource mapping remains
--     live.
[2068] = "Кэш прохода вычисления или nil для прямого наблюдения идентичности. Успешные наблюдения класса игрока могут использовать существующий долговременный кэш идентичности; сопоставление ресурсов остаётся действующим.",
-- 383aa43c English: Evaluation-pass native observation cache; nil queries afresh.
[2069] = "Кэш встроенных наблюдений прохода вычисления; при nil запрос выполняется заново.",
-- bf9ecd5c English: Evaluation-pass presence cache only; name, level and provider history remain
--     fresh.
[2070] = "Кэш прохода вычисления только для присутствия; имя, уровень и история поставщика остаются свежими.",
-- 2dbf0453 English: Exact helper-owned player, party1..party4 or raid1..raid40 token.
[2071] = "Точный токен player, party1..party4 или raid1..raid40, принадлежащий помощнику.",
-- 27bda267 English: Exact integral native rune slot from 1 through 6.
[2072] = "Точная целочисленная встроенная ячейка руны от 1 до 6.",
-- 4fc2d3d1 English: Exact nonempty unit token to observe.
[2073] = "Точный непустой токен наблюдаемого юнита.",
-- c590f11f English: Exact nonempty unit token, passed unchanged.
[2074] = "Точный непустой токен юнита, передаётся без изменений.",
-- fd8065c0 English: Exact readable recipient name recorded for this cast.
[2075] = "Точное читаемое имя получателя, записанное для этого применения.",
-- b05cf3b2 English: Exact selected unit token; only the literal player token may select the TBC
--     combo transport.
[2076] = "Точный токен выбранного юнита; только буквальный токен player может выбрать передачу очков серии TBC.",
-- 19306e82 English: Exact selected unit token; player class alone may use the successful longterm
--     cache.
[2077] = "Точный токен выбранного юнита; успешный долговременный кэш может использовать только класс игрока.",
-- af7eabaa English: Exact selected unit token; the attacker remains player.
[2078] = "Точный токен выбранного юнита; атакующим остаётся player.",
-- c08ce58e English: Exact unit token checked for existence and passed to the selected metadata API.
[2079] = "Точный токен юнита, проверяемый на существование и передаваемый выбранному API метаданных.",
-- eb750dcd English: Exact unit token passed unchanged to UnitExists and, when required, UnitClass.
[2080] = "Точный токен юнита, передаваемый без изменений в UnitExists и, при необходимости, в UnitClass.",
-- 3641c328 English: Exact unit token used for existence and as the recipient of player hostility
--     and threat queries.
[2081] = "Точный токен юнита для проверки существования и как получатель запросов враждебности и угрозы игрока.",
-- 616ee642 English: Exact unit token whose resource should be observed; this does not redirect
--     player or vehicle units.
[2082] = "Точный токен юнита, ресурс которого наблюдается; юниты игрока или транспорта не перенаправляются.",
-- f89b30c5 English: Exact unit token whose selected flag should be observed.
[2083] = "Точный токен юнита, выбранный флаг которого наблюдается.",
-- bb716e79 English: Exact unit token whose selected resource quantity is requested.
[2084] = "Точный токен юнита, для которого запрашивается выбранное количество ресурса.",
-- d07d5f8c English: Exactly current for UnitPower or maximum for UnitPowerMax.
[2085] = "Ровно current для UnitPower или maximum для UnitPowerMax.",
-- 3234a7b8 English: Exactly current for UnitPower or maximum for UnitPowerMax; no other native
--     query is added.
[2086] = "Ровно current для UnitPower или maximum для UnitPowerMax; других встроенных запросов не добавляется.",
-- ce5b4817 English: Exactly current for the player/target combo query or maximum for the player
--     capacity query.
[2087] = "Ровно current для запроса очков серии игрока/цели или maximum для запроса ёмкости игрока.",
-- 01112dbd English: Exactly dead for UnitIsDeadOrGhost, or friendly for UnitIsFriend(player, unit).
[2088] = "Ровно dead для UnitIsDeadOrGhost или friendly для UnitIsFriend(player, unit).",
-- 572b3dd2 English: Exactly type or school; selects the required subject field without requiring
--     the other.
[2089] = "Ровно type или school; выбирает нужное поле субъекта, не требуя другого.",
-- 618e2637 English: Existing stored CREATURE key: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT,
--     UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET or GAS_CLUUD.
[2090] = "Существующий сохранённый ключ CREATURE: BEAST, DRAGONKIN, DEMON, ELEMENTAL, GIANT, UNDEAD, HUMANOID, CRITTER, MECHANICAL, OTHER, TOTEM, NONCOMBAT_PET или GAS_CLUUD.",
-- 93af5992 English: Explicit finite clock snapshot; signed and fractional values remain valid.
[2091] = "Явный конечный снимок часов; знаковые и дробные значения допустимы.",
-- b6d72a06 English: Explicit finite weighting window; no profile fallback or clamp.
[2092] = "Явное конечное окно взвешивания; без запасного значения из профиля и без усечения.",
-- 8775b9a4 English: Explicit nonnegative integer power selector, false for a known absent unit, or
--     nil when required data is unavailable.
[2093] = "Явный неотрицательный целочисленный выбор ресурса, false для известного отсутствующего юнита или nil, если обязательные данные недоступны.",
-- 593273d6 English: Explicit nonnegative integer selector, false for known unit absence, or nil
--     when required data is unavailable.
[2094] = "Явный неотрицательный целочисленный выбор, false при известном отсутствии юнита или nil, если обязательные данные недоступны.",
-- 18dcc116 English: Explicit readable finite nonnegative integer power selector, including zero.
[2095] = "Явный читаемый конечный неотрицательный целочисленный выбор ресурса, включая ноль.",
-- 4cb2bf6f English: Explicit readable finite nonnegative integer power selector.
[2096] = "Явный читаемый конечный неотрицательный целочисленный выбор ресурса.",
-- cdbf6c56 English: Finite ETA including zero, false for known absence/no estimate, or nil when
--     unavailable.
[2097] = "Конечное оставшееся время, включая ноль; false при известном отсутствии или отсутствии оценки; nil, если недоступно.",
-- a4382b09 English: Finite final stream age, or nil when unavailable.
[2098] = "Конечный итоговый возраст потока или nil, если недоступен.",
-- 84e16e8d English: Finite minimum native threat status, preserving signed and fractional
--     thresholds.
[2099] = "Конечный минимальный встроенный статус угрозы с сохранением знаковых и дробных порогов.",
-- 7e3a2158 English: Finite native creature ID, false for known unit absence, or nil when required
--     observations are unavailable.
[2100] = "Конечный встроенный ID существа, false при известном отсутствии юнита или nil, если обязательные наблюдения недоступны.",
-- 3dd70e07 English: Finite native resource quantity, retaining its sign and fractional part; nil
--     when unavailable.
[2101] = "Конечное встроенное количество ресурса с сохранением знака и дробной части; nil, если недоступно.",
-- 3931aa80 English: Finite native threat status, false for known absence/nonenemy/no-threat, or nil
--     for unavailable observations.
[2102] = "Конечный встроенный статус угрозы; false при известном отсутствии, не-противнике или отсутствии угрозы; nil для недоступных наблюдений.",
-- 9cb9f6d2 English: Finite nonnegative native health scalar, or nil when unavailable.
[2103] = "Конечное неотрицательное встроенное значение здоровья или nil, если недоступно.",
-- aa23a412 English: Finite quantity in whole units with its fractional part; nil when unavailable.
[2104] = "Конечное количество в целых единицах с дробной частью; nil, если недоступно.",
-- 29e4a6a2 English: Finite signed combined rate, or nil for unavailable calculation.
[2105] = "Конечная знаковая общая скорость или nil, если расчёт недоступен.",
-- 94c010ef English: First exact unit token, checked for existence before comparison.
[2106] = "Первый точный токен юнита, проверяемый на существование перед сравнением.",
-- 46ec876e English: First table to compare.
[2107] = "Первая сравниваемая таблица.",
-- 13e6df72 English: Format comparison wording with named Boolean alternatives when the operator has
--     a negative form. The primary flag marks the positive form as the primary alternative.
--     Positive operator labels use the captured operator map; negative labels and nullable dispatch
--     retain their live addon APIs.
[2108] = "Сформировать текст сравнения с именованными логическими вариантами, если у оператора есть отрицательная форма. Флаг primary помечает положительную форму как основной вариант. Подписи положительных операторов берутся из захваченной таблицы операторов; отрицательные подписи и обработка nil сохраняют действующие API аддона.",
-- b0edcb9b English: Fresh finite native clock value, or nil when unavailable.
[2109] = "Свежее конечное встроенное значение часов или nil, если недоступно.",
-- b3a296d8 English: Fresh readable class filename, or nil when unavailable.
[2110] = "Свежее читаемое имя файла класса или nil, если недоступно.",
-- 16428e88 English: Fresh readable finite clock, or nil when unavailable.
[2111] = "Свежие читаемые конечные часы или nil, если недоступны.",
-- 2078f2c6 English: Fresh readable record with active, then name or nameReason, remainingSeconds,
--     durationSeconds, interruptible and spellID. Remaining time and duration are in seconds;
--     remaining time is clamped to zero. An unavailable optional field has its own reason; it does
--     not invalidate an active record.
[2112] = "Свежая читаемая запись с active, затем name или nameReason, remainingSeconds, durationSeconds, interruptible и spellID. Оставшееся время и длительность указаны в секундах; оставшееся время не опускается ниже нуля. Недоступное необязательное поле имеет собственную причину и не делает активную запись недействительной.",
-- 47a58974 English: Fresh readable record with exists and, when present, a positive integer level.
[2113] = "Свежая читаемая запись с exists и, если юнит есть, положительным целым level.",
-- a25abeed English: Fresh readable record with exists and, when present, current health. Maximum
--     health is included only when requested.
[2114] = "Свежая читаемая запись с exists и, если юнит есть, текущим здоровьем. Максимальное здоровье включается только по запросу.",
-- 21290700 English: Fresh readable record with exists and, when present, powerType and finite
--     current quantity. Requested maximum is finite and nonnegative. Quantities may be fractional;
--     current-mode current may be signed.
[2115] = "Свежая читаемая запись с exists и, если юнит есть, powerType и конечным текущим количеством. Запрошенный максимум конечен и неотрицателен. Количества могут быть дробными; в режиме current текущее значение может быть знаковым.",
-- 681f8ad6 English: Fresh readable record with finite nonnegative speed, or nil when unavailable.
[2116] = "Свежая читаемая запись с конечной неотрицательной скоростью или nil, если недоступно.",
-- abf7477d English: Function or global function name to call.
[2117] = "Функция или имя глобальной функции для вызова.",
-- 9d253f49 English: History record with newest-first damage and heals arrays of time/value entries.
--     Falsy history returns only zero without reading the clock.
[2118] = "Запись истории с массивами урона и исцеления из записей время/значение, новые первыми. При ложной истории возвращается только ноль без чтения часов.",
-- 8deb9947 English: Identifier-keyed scalar values or typed predicates. Strings, finite numbers and
--     booleans are supported; referenced slots must be present. Values are captured when the phrase
--     is created.
[2119] = "Скалярные значения или типизированные предикаты с ключами-идентификаторами. Поддерживаются строки, конечные числа и логические значения; используемые ячейки должны присутствовать. Значения захватываются при создании фразы.",
-- b1c195d7 English: Insert each value visited by ipairs at its corresponding leading index in the
--     destination array. Existing entries shift after the inserted prefix; traversal stops at the
--     first missing source index.
[2120] = "Вставить каждое значение, обходимое ipairs, по соответствующему начальному индексу в массив назначения. Существующие записи сдвигаются за вставленный префикс; обход останавливается на первом отсутствующем индексе источника.",
-- db2baa62 English: Integral RM statistic selector 1..5, or 6 for effective armor.
[2121] = "Целочисленный выбор характеристики RM 1..5 или 6 для эффективной брони.",
-- c406e603 English: Iterator yielding a captured key and its current table value, or no values when
--     exhausted.
[2122] = "Итератор, выдающий захваченный ключ и его текущее значение в таблице, или ничего, когда ключи закончились.",
-- ce63ac6d English: Key to look up.
[2123] = "Искомый ключ.",
-- 3638b5da English: Known active count from zero through the RM scan budget, or nil when
--     unavailable.
[2124] = "Известное число активных — от нуля до бюджета сканирования RM — или nil, если недоступно.",
-- 101d17c0 English: Known nonempty role string, false for known absent unit, or nil when
--     unavailable.
[2125] = "Известная непустая строка роли, false для известного отсутствующего юнита или nil, если недоступно.",
-- 5194c38b English: Known nonempty role string, or nil when unavailable.
[2126] = "Известная непустая строка роли или nil, если недоступно.",
-- 74c5fd96 English: Known unit presence or absence; nil when the required observation is
--     unavailable.
[2127] = "Известное присутствие или отсутствие юнита; nil, если обязательное наблюдение недоступно.",
-- 337a2aa3 English: Larger rounded stream age in seconds, not a sample count or proof of continuous
--     observation. Omitted when history is falsy.
[2128] = "Больший округлённый возраст потока в секундах — не число выборок и не доказательство непрерывного наблюдения. Опускается, если история ложна.",
-- 289c0861 English: Left operand; use numbers for ordering and divisibility.
[2129] = "Левый операнд; для упорядочивания и делимости используйте числа.",
-- c6b39836 English: Literal prefix, including an empty prefix.
[2130] = "Буквальный префикс, в том числе пустой.",
-- 8bc05b19 English: Literal suffix, including an empty suffix.
[2131] = "Буквальный суффикс, в том числе пустой.",
-- 696821ba English: Live selected talent-group argument, forwarded unchanged as one argument after
--     readability checking.
[2132] = "Действующий аргумент выбранной группы талантов, передаётся без изменений одним аргументом после проверки читаемости.",
-- 55c2262c English: Localized complete sentence with named slots and optional explicit predicate
--     alternatives.
[2133] = "Локализованное законченное предложение с именованными ячейками и необязательными явными вариантами предиката.",
-- ebab9399 English: Look up a table key for display, preserving non-nil results; invalid tables,
--     missing keys and nil keys use nullable placeholder text.
[2134] = "Найти ключ таблицы для отображения, сохраняя результаты не nil; для некорректных таблиц, отсутствующих ключей и ключей nil используется текст-заполнитель.",
-- d27c5ef2 English: Lookup key.
[2135] = "Ключ поиска.",
-- d746509f English: Lua pattern character-class separator, default %s for whitespace.
-- %s #1: %s #1: not a placeholder; it is the literal Lua pattern class for whitespace, shown to the user as text, e.g. "default %s for whitespace". Keep %s exactly as written.
[2136] = "Разделитель — класс символов шаблона Lua, по умолчанию %s для пробельных символов.",
-- 3aeb0664 English: Mark the positive wording as the primary named alternative.
[2137] = "Пометить положительную формулировку как основной именованный вариант.",
-- 44dec6d3 English: Matching key, including a false key, or nil when no match exists.
[2138] = "Совпадающий ключ, включая ключ false, или nil, если совпадений нет.",
-- 75ef3e00 English: Missing-value display text; omitted uses the localized value placeholder.
[2139] = "Текст для отсутствующего значения; если опущен, используется локализованный заполнитель значения.",
-- 15f81670 English: Native button with label, disabled state and lease-protected callbacks.
[2140] = "Встроенная кнопка с подписью, состоянием отключения и обратными вызовами, защищёнными арендой.",
-- 8eb10f5d English: Native directional pad with center reset and lease-protected callbacks.
[2141] = "Встроенная панель направлений со сбросом в центр и обратными вызовами, защищёнными арендой.",
-- bb0ac63a English: Native image control with label, texture, disabled state and callbacks.
[2142] = "Встроенный элемент изображения с подписью, текстурой, состоянием отключения и обратными вызовами.",
-- 43cf01e1 English: Native interactive text and image control with measured height and disabled
--     state.
[2143] = "Встроенный интерактивный элемент текста и изображения с измеряемой высотой и состоянием отключения.",
-- 990a6544 English: Native one-based integral active-row index within the 256-row RM scan budget.
[2144] = "Встроенный целочисленный индекс активной строки (с единицы) в пределах бюджета сканирования RM в 256 строк.",
-- 7e3aed01 English: Native wrapping text control with font, color and alignment methods.
[2145] = "Встроенный элемент переносимого текста с методами шрифта, цвета и выравнивания.",
-- d76c2067 English: New shallow filtered table, or nil for nil input.
[2146] = "Новая неглубокая отфильтрованная таблица или nil при входе nil.",
-- 50f7bd28 English: New table with stringified keys and unchanged values.
[2147] = "Новая таблица со строковыми ключами и неизменёнными значениями.",
-- f1052f11 English: Newest-first health snapshots containing time, value and max. Falsy input
--     returns only zero without reading the clock.
[2148] = "Снимки здоровья (новые первыми), содержащие time, value и max. При ложном входе возвращается только ноль без чтения часов.",
-- 7276d3c4 English: No return values. The destination array is modified in place.
[2149] = "Нет возвращаемых значений. Массив назначения изменяется на месте.",
-- 69c24773 English: No return values. The supplied table is modified in place.
[2150] = "Нет возвращаемых значений. Переданная таблица изменяется на месте.",
-- da87cc23 English: Nonempty class filename token to count; no class-token whitelist is applied.
[2151] = "Непустой токен имени файла класса для подсчёта; белый список токенов классов не применяется.",
-- 3694f9ed English: Nonempty historical school key for resist/immune; unused for runner.
[2152] = "Непустой исторический ключ школы для resist/immune; для runner не используется.",
-- 7ee44b6f English: Normalized bounded socket snapshot with slots and complete, or nil when the
--     query is unavailable.
[2153] = "Нормализованный ограниченный снимок гнёзд со slots и complete или nil, если запрос недоступен.",
-- 93ec5fb4 English: Normalized requested subject with finite timeRemaining or timeRemainingReason;
--     nil when the required row or subject is unavailable.
[2154] = "Нормализованный запрошенный субъект с конечным timeRemaining или timeRemainingReason; nil, если обязательная строка или субъект недоступны.",
-- 7663ebe1 English: Number of entries visited.
[2155] = "Число обойдённых записей.",
-- 7f36a397 English: Number or string to inspect; other types do not match.
[2156] = "Проверяемое число или строка; другие типы не совпадают.",
-- 4e6ddf17 English: Numeric widget supporting slider bounds, percent display and pending-edit
--     validation.
[2157] = "Числовой виджет с границами ползунка, отображением процентов и проверкой ожидающей правки.",
-- c8144d6f English: Observation kind: cast or channel. These use different native interruptibility
--     tuple positions.
[2158] = "Вид наблюдения: cast или channel. У них разные позиции признака прерываемости во встроенном кортеже.",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2159] = "Причина недоступности наблюдения, истории, предела работы или арифметики.",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2160] = "Получить свежее значение защищённого вызова GetTime без аргументов для нужного прогноза здоровья. Требуются читаемость и конечное число; знаковые и дробные значения сохраняются без ограничений монотонности, целочисленности или неотрицательности. Кэш часов и дополнительные встроенные запросы не используются.",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2161] = "Наблюдать очки ресурса, которые клиент сообщает частями (Раскаленные угли в Mists of Pandaria). Для current используется ровно UnitPower(unit,powerType,true), для maximum — UnitPowerMax(unit,powerType,true); результат делится на MAX_POWER_PER_EMBER от Blizzard (10), поэтому 35 частей — это 3,5. Только политика проверки. Отсутствующие, неудачные, ограниченные или повреждённые данные остаются недоступными; запрос в целых единицах никогда не используется как запасной вариант. Кэш не добавляется.",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2162] = "Наблюдать читаемый исходный уровень юнита на известных клиентах. Читаемо отсутствующий юнит возвращает exists=false; для присутствующих юнитов нужен положительный конечный целый UnitLevel. Неизвестный уровень босса, отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной. Эффективные или масштабированные уровни не используются.",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2163] = "Наблюдать роль выбранного юнита на клиентах с политикой проверки или ограничения без запросов осмотра. Известное отсутствие юнита возвращает false. Предпочитается вызываемый современный API осмотра, а старый вариант — только если вызываемого нет; ошибка выбранного варианта никогда не переходит к другому. Требуется положительный конечный целый ID специализации, и используется только пятое возвращаемое значение (роль) точного вызова GetSpecializationInfoByID с одним аргументом. Отсутствующие, неудачные, ограниченные или повреждённые обязательные факты недоступны; читаемые непустые будущие строки ролей сохраняются точно.",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2164] = "Наблюдать произнесение или поддержание заклинания юнитом на клиентах с политикой проверки или ограничения. Известное отсутствие юнита или читаемый неактивный результат возвращает active=false. Активные записи содержат name либо nameReason, если имя секретно (юнит всё равно произносит заклинание), а также независимо доступные поля remainingSeconds, durationSeconds, interruptible и spellID с remainingReason, durationReason, interruptibleReason или spellReason, если необязательное поле недоступно. Отсутствующие, неудачные или ограниченные наблюдения присутствия возвращают nil с причиной.",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2165] = "Наблюдать идентичность существа по второму возвращаемому значению встроенного UnitCreatureType на клиентах с политикой проверки или ограничения. Сначала проверяется точный UnitExists(unit); читаемое false возвращает false без запроса метаданных существа. Для присутствующего юнита нужен читаемый конечный числовой ID; неиспользуемое локализованное название на доступность не влияет. Знаковые, дробные, нулевые и будущие конечные ID сохраняются как известные значения. Отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные факты возвращают nil с причиной. Перечисление существ, сравнение переведённых подписей и долговременный кэш не добавляются.",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2166] = "Наблюдать состояние смерти или призрака либо дружелюбие к игроку для точного выбранного юнита на клиентах с политикой проверки или ограничения. Отсутствующее, неудачное, ограниченное или повреждённое обязательное наблюдение недоступно. Отсутствие юнита — это «недоступно», а не отрицательное совпадение, в том числе под НЕ. Состояние между опросами не сохраняется.",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2167] = "Наблюдать точное существование питомца и, при необходимости, его отформатированное отображаемое имя через GetUnitName. Запросы только присутствия никогда не требуют имени. При известном отсутствии запрос имени пропускается. Для присутствующих питомцев читаемое непустое имя требуется только по запросу; отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Помощник отображения вызывается с единственным исходным аргументом питомца, без запасного UnitName и без выводов о панели, здоровье или способностях.",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2168] = "Наблюдать точное существование выбранного юнита и, при необходимости, имя файла его класса для условий по очкам ресурса. Известное отсутствие возвращает exists=false без чтения класса. Для присутствующих юнитов по запросу нужно только второе возвращаемое значение UnitClass; неиспользуемые локализованные названия и ID на доступность не влияют. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения остаются недоступными. Ресурс не выбирается, идентичность не кэшируется.",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2169] = "Наблюдать явно ману или текущий исходный ресурс на поддерживаемых читаемых клиентах. Идентичность ресурса выбирается из действующего перечисления PowerType; явная мана никогда не заменяется текущей полосой. Известное отсутствие возвращает exists=false; отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной. Количества в режиме current сохраняют знак встроенных ресурсов; явная мана неотрицательна. Максимум запрашивается только при необходимости; потребители процентов должны требовать положительный максимум.",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2170] = "Наблюдать гнёзда символов на проверенных раскладках клиентов Wrath, Cata и Mists. Возвращает slots и флаг complete. У каждой ячейки active=false, если она известно заблокирована или пуста, active=true и spellID, если занята, или active=nil и причина, если недоступна. Неизвестные раскладки и неудачные запросы количества возвращают nil с причиной. Названия предметов не сравниваются, точное соответствие предмета заклинанию не доказывается.",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2171] = "Наблюдать одно используемое поле встроенных метаданных юнита после проверки UnitExists: class — второе значение UnitClass, creature — локализованное название UnitCreatureType, classification — UnitClassification. Читаемо отсутствующий юнит возвращает false без запроса метаданных. Неиспользуемые поля кортежа на доступность не влияют; отсутствующее, неудачное, nil, ограниченное или повреждённое обязательное значение возвращает nil с причиной. Класс игрока, GUID, перечисления или переводы не выводятся.",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2172] = "Наблюдать один текущий флаг юнита: combat — UnitAffectingCombat, enemy — UnitIsEnemy с player первым юнитом, pvp — UnitIsPVP. Читаемо отсутствующий юнит возвращает false без запроса флага. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Точный выбранный юнит сохраняется; дружелюбие, возможность атаки и другие состояния юнита не выводятся.",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2173] = "Наблюдать одну точную встроенную ячейку руны через GetRuneType с единственным аргументом-индексом. Нужен читаемый конечный положительный целый тип; известные будущие числовые типы остаются отличными от выбранного, а «Смерть» — точный тип, а не подстановочный. Отсутствующие, неудачные, ограниченные или повреждённые наблюдения остаются недоступными. Запросы класса, юнита, количества или выведенной базовой руны не добавляются.",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2174] = "Наблюдать один независимый флаг игрока без аргументов: stealthed — IsStealthed, control — HasFullControl, outdoors — IsOutdoors. Читаемые true и false сохраняют свой смысл. Отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные данные возвращают nil с причиной. Выводы о существовании, подземелье или применимости способностей не добавляются.",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2175] = "Наблюдать один защищённый кортеж IsInInstance без аргументов. Обязательное читаемое логическое значение нахождения не зависит от поля типа: известное «снаружи» возвращается без разбора неиспользуемого типа; «внутри» возвращает читаемую строку типа или instanceTypeReason, если это вторичное поле недоступно. Проверяющим «снаружи» достаточно факта нахождения; сравнения типа «внутри» должны проверять вторичную причину. Выводы о нахождении под открытым небом, зоне или юните не добавляются.",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2176] = "Наблюдать по порядку существование выбранного юнита, враждебность к игроку, затем статус угрозы игрока по этому юниту. Известное отсутствие, не-противник и успешно прочитанный статус угрозы nil возвращают false, сохраняя предикат «нет угрозы». Конечные значения статуса, включая ноль, сохраняют исходный смысл сравнения. Отсутствующие, неудачные, nil, ограниченные или повреждённые обязательные факты возвращают nil с причиной. Выводы о возможности атаки, смерти, бое или транспорте не добавляются.",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2177] = "Наблюдать читаемое текущее и, при необходимости, максимальное здоровье на поддерживаемых клиентах. Читаемо отсутствующий юнит возвращает exists=false. Отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной; они не означают отсутствия юнита или значения здоровья.",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2178] = "Наблюдать текущий облик игрока одним защищённым вызовом GetShapeshiftForm без аргументов. Сохраняется любой читаемый конечный числовой результат, включая ноль, знаковые и дробные значения; более строгая область индексов не выводится. Отсутствующие, неудачные, nil, ограниченные или бесконечные данные остаются недоступными. Число обликов, класс, ID заклинания, юнит или необязательный аргумент не добавляются.",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2179] = "Наблюдать эффективную характеристику только по второму встроенному возвращаемому значению. На клиентах с политикой проверки или ограничения запрашивается точный UnitExists(unit), затем UnitStat(unit,stat) для выбора 1..5 или UnitArmor(unit) для выбора 6. Известное отсутствие возвращает exists=false; отсутствующие, неудачные, ограниченные или бесконечные обязательные факты возвращают nil. Конечные знаковые, дробные и нулевые значения сохраняются; все неиспользуемые поля кортежа игнорируются. Путь 1..6 — правило выбора RM, а не ограничение области встроенных значений.",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2180] = "Наблюдать явно выбранную передачу очков серии игрока в TBC. Для current используется ровно GetComboPoints(player,target); для maximum — UnitPowerMax(player,powerType) с исходным выбором. Другие семейства здесь недоступны и должны использовать свой существующий наблюдатель очков ресурса. Читаемые конечные знаковые, дробные и нулевые значения сохраняются. Отсутствующие, неудачные, ограниченные или повреждённые данные остаются недоступными; неудачный выбранный запрос очков серии никогда не переходит к UnitPower. Другие участники не наблюдаются, кэш не добавляется.",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2181] = "Наблюдать первый результат роли точного старого вызова GetTalentGroupRole(group) через точку на клиентах с политикой проверки или ограничения. Читаемая выбранная группа передаётся без изменений, включая nil как один аргумент; границы группы не выводятся, другой API не подставляется, юнит игрока не запрашивается. Полное старое объявление основной роли не устанавливается. Отсутствующие, неудачные, ограниченные, пустые или повреждённые данные роли недоступны; читаемые непустые будущие строки сохраняются точно.",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2182] = "Наблюдать первый результат классификации PvP зоны одним защищённым вызовом через точку без аргументов. Предпочитается вызываемый C_PvP.GetZonePVPInfo, а глобальный помощник используется, только если современного вызова нет. Успешный nil или отсутствие возвращаемых значений дают известную пустую запись; отсутствующие, неудачные, ограниченные или повреждённые наблюдения остаются недоступными. Читаемые пустые и будущие строки сохраняют точный смысл, а неиспользуемые возвращаемые поля не определяют доступность. После результата или ошибки современного варианта переключение на другой никогда не происходит.",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2183] = "Наблюдать текущую скорость передвижения игрока на поддерживаемых читаемых клиентах. Запрашивается GetUnitSpeed только для player, без проверки других юнитов и без перенаправления на транспорт. Ноль — стоит на месте; положительные конечные дробные скорости допустимы. Отсутствующие, неудачные, ограниченные или повреждённые наблюдения возвращают nil с причиной.",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2184] = "Наблюдать присутствие юнита на определённых семействах клиентов. Выбранный юнит передаётся без изменений в один защищённый вызов UnitExists. Читаемые true и false сохраняются; отсутствующие, неудачные, ограниченные, nil или повреждённые обязательные наблюдения возвращают nil с причиной. Запросы идентичности, видимости, дальности или боевого состояния не добавляются.",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2185] = "Наблюдать, может ли игрок атаковать выбранный юнит, который не мёртв, с помощью точных предикатов UnitExists, UnitCanAttack и UnitIsDead. Известное отсутствие или читаемый отрицательный результат атаки возвращают false без запроса смерти. Отсутствующие, неудачные, ограниченные или повреждённые обязательные наблюдения возвращают nil с причиной. Призраки, дальность, враждебность и применимость способностей не проверяются, принадлежность юнита не перенаправляется.",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2186] = "Наблюдаемая строка имени файла класса, false для известного отсутствующего юнита или nil, если недоступно.",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2187] = "Наблюдаемое членство или nil, если недоступно.",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2188] = "Только для выбранного ресурса: target-combo для явного запасного варианта игрока TBC или power для существующей передачи выбранного юнита.",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2189] = "На клиентах с политикой проверки или ограничения наблюдать точный UnitExists(unit), затем UnitGUID(unit) только для присутствующего юнита. Известное отсутствие — false. Для идентичности присутствующего юнита нужен читаемый непустой GUID; отсутствующие, неудачные, повреждённые или ограниченные обязательные факты недоступны. Наблюдения здоровья, поставщика или дополнительных юнитов не добавляются.",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2190] = "Одно из class, creature или classification; другие виды метаданных не поддерживаются.",
-- f4dbfa56 English: One of combat, enemy or pvp; other flag kinds are not supported.
[2191] = "Одно из combat, enemy или pvp; другие виды флагов не поддерживаются.",
-- 6a9d3fdc English: One of stealthed, control or outdoors; no other predicate is invoked.
[2192] = "Одно из stealthed, control или outdoors; другие предикаты не вызываются.",
-- e7332ebe English: One rounded numeric result from the original formula.
[2193] = "Один округлённый числовой результат по исходной формуле.",
