[2886] = "Ваша собственная ротация используется только на вашей панели, если только её условие переключения этим условием не требует другого контекста действий; тогда она используется, а её кнопки ищутся, пока показана та панель.",
-- fcefef14 English: Currently: no temporary enchant
[2887] = "Сейчас: нет временных чар",
