[3006] = "%s {{!повторяется автоматически|не повторяется автоматически}}",
-- 9544d41a English: Tests whether the selected spell is currently auto-repeating, such as Shoot or
--     Auto Shot. This is different from a spell being current or queued: a queued cast alone does
--     not satisfy this condition. Unavailable client observations remain unavailable even when
--     negated.
[3007] = "Проверяет, повторяется ли сейчас выбранное заклинание автоматически, например «Выстрел» или «Автоматическая стрельба». Это не то же самое, что текущее или поставленное в очередь заклинание: одно лишь применение в очереди этому условию не удовлетворяет. Недоступные наблюдения клиента остаются недоступными даже при отрицании.",
-- 32d5dd3a English: Uses readable positions in the same instance, or player-centered range
--     estimates when positions are unavailable. A unit counts only when its upper range bound is
--     within Distance. Uncertain positions, range, subgroup membership or required health/mana
--     values keep the whole condition unavailable, including under Unless. Percentage checks
--     require a positive maximum; empty aggregates have no result.
[3008] = "Использует читаемые позиции в том же подземелье или, если позиции недоступны, оценки дальности относительно игрока. Юнит учитывается, только если верхняя граница его дальности не больше «Дистанции». Неопределённые позиции, дальность, принадлежность к подгруппе или нужные значения здоровья/маны делают всё условие недоступным, в том числе под «Если не». Для процентных проверок нужен положительный максимум; у пустых агрегатов нет результата.",
-- 4953738e English: Count enemies when selected, or non-enemies when cleared.
[3009] = "Если отмечено — считать противников, если нет — не-противников.",
-- 5179228a English: The number of observed units proven within Distance of you.
[3010] = "Число наблюдаемых юнитов, достоверно находящихся в пределах «Дистанции» от вас.",
-- 5f3da9f5 English: Counts the addon's observed unit snapshot, including nameplates and tracked
--     unit aliases, rather than every nearby unit. A unit counts only when its upper range bound is
--     within Distance; uncertain membership or unreadable identity, hostility, range or nameplate
--     settings makes the whole count unavailable, including under Unless. Known vanished or reused
--     unit tokens are excluded. Distance cannot exceed the current nameplate distance setting; that
--     setting does not guarantee a complete scan.
[3011] = "Считает снимок наблюдаемых аддоном юнитов, включая индикаторы здоровья и отслеживаемые псевдонимы юнитов, а не все юниты поблизости. Юнит учитывается, только если верхняя граница его дальности не больше «Дистанции»; неопределённая принадлежность или нечитаемые идентичность, враждебность, дальность или настройки индикаторов делают весь подсчёт недоступным, в том числе под «Если не». Известные исчезнувшие или переиспользованные токены юнитов исключаются. «Дистанция» не может превышать текущую настройку дальности индикаторов здоровья; эта настройка не гарантирует полного охвата.",
-- 60bfbfa2 English: you {{!have|do not have}} {item} equipped
[3012] = "у вас {{!надет|не надет}} {item}",
-- 1d06a92b English: {item} {{!is|is not}} available{carrying}
[3013] = "{item}: {{!доступно|недоступно}}{carrying}",
-- ac058958 English: {item} {{!is|is not}} in range{carrying}
[3014] = "{item}: {{!в зоне досягаемости|вне зоны досягаемости}}{carrying}",
-- 216e438b English: the cooldown on {item} {comparison} {duration}{carrying}
[3015] = "восстановление {item} {comparison} {duration}{carrying}",
-- 623bd8c4 English: {unit} {{!is|is not}} in a group
[3016] = "{unit} {{!в группе|не в группе}}",
-- fedfc418 English: {unit} {{!is friendly to you|is not friendly to you}}
[3017] = "{unit} {{!дружелюбен к вам|не дружелюбен к вам}}",
-- 6e21eee4 English: Matches when the selected unit is dead or a ghost. A missing or unreadable unit
--     is unavailable, including under NOT. In a Via Macro announcement, choose Announcement target
--     to follow the supplied unit.
[3018] = "Срабатывает, если выбранный юнит мёртв или в облике призрака. Отсутствующий или нечитаемый юнит недоступен, в том числе под НЕ. В оповещении «Через макрос» выберите «Цель оповещения», чтобы использовать переданный юнит.",
-- eaa8232a English: Matches when the game reports the selected unit as friendly to you. This does
--     not imply party or raid membership. A missing or unreadable unit is unavailable.
[3019] = "Срабатывает, когда игра сообщает, что выбранный юнит дружелюбен к вам. Это не означает членства в группе или рейде. Отсутствующий или нечитаемый юнит недоступен.",
-- b9151b16 English: Assisted Combat {{!is|is not}} suggesting a spell
[3020] = "Боевой помощник {{!предлагает|не предлагает}} заклинание",
-- 43bf497e English: Assisted Combat {{!suggests|does not suggest}} %s
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3021] = "Боевой помощник {{!предлагает|не предлагает}} %s",
-- 6c9594a9 English: Matches when Blizzard's Assisted Combat suggests this spell as the next cast.
--     An override counts as its base spell, and the base spell as its override. With no spell
--     chosen, matches whenever Assisted Combat suggests anything.
[3022] = "Срабатывает, когда Боевой помощник Blizzard предлагает это заклинание для следующего применения. Замещающее заклинание считается своим базовым, а базовое — своим замещающим. Если заклинание не выбрано, срабатывает всякий раз, когда Боевой помощник что-либо предлагает.",
-- 44e850ce English: Assisted Combat exists on Retail (and is declared on Forever). Where the game
--     does not offer it, for this character or specialization, or the suggestion cannot be read,
--     this condition is unavailable rather than false, including under NOT.
[3023] = "Боевой помощник есть в Retail (и объявлен в Forever). Там, где игра его не предоставляет (для этого персонажа или специализации), или где предложение нельзя прочитать, это условие недоступно, а не ложно, в том числе под НЕ.",
-- 32c737f7 English: %s {{!is|is not}} in Blizzard's Assisted Combat rotation
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3024] = "%s {{!входит|не входит}} в ротацию Боевого помощника Blizzard",
-- ae726224 English: Matches when this spell is one Blizzard's Assisted Combat can suggest for your
--     current specialization. Its current override and its base spell count too. Use it to
--     highlight what Assisted Combat leaves out, for example a cooldown that is not in the set.
[3025] = "Подходит, если это заклинание — одно из тех, что Боевой помощник Blizzard может предложить для вашей текущей специализации. Его текущая замена и базовое заклинание тоже учитываются. Используйте, чтобы подсветить то, что Боевой помощник оставляет без внимания, например перезарядку, которой нет в наборе.",
-- 2a9b9d24 English: The set is read again whenever your spells change, never guessed. Where the
--     game does not offer Assisted Combat for this character or specialization, or the set cannot
--     be read, this condition is unavailable rather than false, including under NOT.
[3026] = "Набор перечитывается при каждом изменении ваших заклинаний, а не угадывается. Если игра не предлагает Боевого помощника для этого персонажа или специализации либо набор нельзя прочитать, это условие недоступно, а не ложно, в том числе под НЕ.",
-- 10ac60e3 English: Assisted Combat {{!is|is not}} available
[3027] = "Боевой помощник {{!доступен|недоступен}}",
-- d882c8a9 English: Matches when the game offers Blizzard's Assisted Combat for your character and
--     current specialization. When it does not (for example a specialization Blizzard has no
--     Assisted Combat rotation for, or a client that declares the API but does not offer the
--     feature), this is false, so a branch can fall back to your own steps.
[3028] = "Подходит, если игра предлагает Боевого помощника Blizzard для вашего персонажа и текущей специализации. Если не предлагает (например, для специализации, у которой у Blizzard нет ротации Боевого помощника, или на клиенте, который объявляет API, но не предлагает эту функцию), условие ложно, поэтому ветвь может перейти к вашим собственным шагам.",
-- 65331c0d English: Unavailable only where the client has no Assisted Combat API or its answer
--     cannot be read, including under NOT.
[3029] = "Недоступно только там, где у клиента нет API Боевого помощника или его ответ нельзя прочитать, в том числе под НЕ.",
